(function(){
'use strict';
const examples={
 presentation:{title:'Tomorrow’s presentation, organized.',tag:'EXAMPLE / PRESENTATION OUTLINE',summary:'A short presentation outline for a fictional bakery’s office catering offer.',points:['A clear audience and offer','Slide structure and speaker notes','An approval checklist before export'],messages:[['client','Maya, turn my catering notes into a short presentation PDF for tomorrow. Let me know when the draft is ready.'],['assistant','Please share the approved offer, audience and notes. I’ll confirm scope and the deadline, then coordinate the presentation draft.'],['assistant','Example result: the presentation draft is ready for your review. The sample alongside shows the structure and approval checklist.']],file:'presentation'},
 launch:{title:'An idea worth investigating.',tag:'EXAMPLE / PRODUCT LAUNCH BRIEF',summary:'A short launch brief for a fictional local meal-prep service. Assumptions are labelled; no demand or sales claims are invented.',points:['Who the first customer might be','Questions to test before launch','A practical first-week validation plan'],messages:[['client','I want to launch a meal-prep service. Prepare a short business report and tell me what I should check before starting.'],['assistant','Which city, audience and delivery area? For the free launch brief we’ll focus on one idea and one market, using your facts and clearly labelled assumptions.'],['assistant','Example result: a concise launch brief with open questions and next steps—not a full feasibility study or a sales forecast.']],file:'launch-brief'},
 invoice:{title:'A website event. A recorded next step.',tag:'EXAMPLE / PLANNED CONNECTED WORKFLOW',summary:'A fictional order illustrates how an authorized invoice-and-alert workflow could operate after integration.',points:['Read the confirmed order details','Create one invoice and send through the agreed account','Record the send result and notify the owner'],messages:[['client','When someone orders on my website, email the invoice and send me an update.'],['assistant','First we connect and test your website, invoice rules and authorized sender account. You approve which confirmed events can trigger an email.'],['assistant','Example result: invoice INV-SAMPLE-001, a recorded email result and an owner alert. Duplicate events are checked; failed sends need attention.']],file:'invoice-workflow'},
 start:{title:'From a simple idea to a first work plan.',tag:'EXAMPLE / BUSINESS STARTER PLAN',summary:'A staged plan for a fictional home-based design service, with decisions, deliverables and approval points.',points:['Clarify one offer and its audience','Scope a website and first brand materials','Prepare enquiries, content and a weekly work routine'],messages:[['client','I have a business idea and no website, team or marketing. Where do I begin?'],['assistant','Let’s define your first customer, offer and goal. Start with a short launch brief, then agree the website, materials and work you actually need.'],['assistant','Example result: a staged starter plan. You approve business decisions and spending; the team supports the agreed work rather than promising a whole business overnight.']],file:'starter-plan'}
};
const tabs=[...document.querySelectorAll('[data-example]')],messages=document.querySelector('#sample-messages'),output=document.querySelector('#sample-output'),play=document.querySelector('#play-example');let current='presentation',timer=null,step=0,playing=false;
const node=(tag,text,cls)=>{const el=document.createElement(tag);if(text)el.textContent=text;if(cls)el.className=cls;return el};
function stop(){clearTimeout(timer);timer=null;playing=false;play.textContent='Play example'}
function message(item,animated=false){const el=node('div',null,'demo-message '+item[0]+(animated?' reveal':''));el.append(node('small',item[0]==='client'?'CLIENT':'MAYA'),node('span',item[1]));messages.append(el)}
function render(id){stop();current=id;const example=examples[id];tabs.forEach(tab=>{const selected=tab.dataset.example===id;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1});document.querySelector('#example-panel').setAttribute('aria-labelledby','example-tab-'+id);messages.replaceChildren();example.messages.forEach(item=>message(item));const paper=node('article',null,'sample-paper');paper.append(node('p',example.tag,'paper-tag'),node('h3',example.title),node('p',example.summary));const list=node('ul');example.points.forEach(text=>list.append(node('li',text)));paper.append(list);output.replaceChildren(paper);document.querySelector('#open-sample').href='samples/'+example.file+'.html'}
tabs.forEach((tab,index)=>{tab.onclick=()=>render(tab.dataset.example);tab.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;render(tabs[next].dataset.example);tabs[next].focus()}});
play.onclick=()=>{if(playing){stop();return}if(matchMedia('(prefers-reduced-motion: reduce)').matches){render(current);return}playing=true;play.textContent='Pause example';messages.replaceChildren();step=0;const tick=()=>{message(examples[current].messages[step++],true);if(step<examples[current].messages.length)timer=setTimeout(tick,1300);else stop()};tick()};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
document.querySelector('#choose-launch-report').onclick=()=>{const picker=document.querySelector('#trial-picker');picker.open=true;const item=document.querySelector('#trial-choices input[value="launch_report"]');if(item&&!item.checked){item.checked=true;item.dispatchEvent(new Event('change',{bubbles:true}))}picker.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(item)item.focus()};
// Preserve existing public links after moving detailed builders to Services.
const moved=new Set(['office','team','departments','office-options-route','choose-route','own-office','plans','ecosystem','roadmap','onboarding']);function oldLink(){const id=location.hash.slice(1);if(moved.has(id))location.replace('services.html#'+id)}window.addEventListener('hashchange',oldLink);oldLink();render(current);
})();
